import sys
from datetime import datetime

def parse_time(time_str):
    return datetime.strptime(time_str, '%H:%M').time()

def overlaps(a_start, a_end, b_start, b_end):
    return not (a_end <= b_start or b_end <= a_start)

def book_cmd(parts):
    bid, room, date_str, start_str, end_str = parts
    try:
        start_time = parse_time(start_str)
        end_time = parse_time(end_str)
    except ValueError:
        print(f"INVALID {bid}")
        return

    if end_time <= start_time:
        print(f"INVALID {bid}")
        return

    conflict = None
    for other_bid, other_room, other_date, other_start, other_end in bookings:
        if other_room == room and other_date == date_str:
            other_start_time = parse_time(other_start)
            other_end_time = parse_time(other_end)
            if overlaps(other_start_time, other_end_time, start_time, end_time):
                if conflict is None or other_start_time < parse_time(bookings[conflict][3]):
                    conflict = other_bid
    if conflict:
        print(f"REJECT {bid} {conflict}")
    else:
        bookings.append((bid, room, date_str, start_str, end_str))
        print(f"ACCEPT {bid}")

def cancel_cmd(parts):
    target_bid = parts[1]
    global bookings
    bookings = [b for b in bookings if b[0] != target_bid]
    if target_bid not in [b[0] for b in bookings]:
        print(f"UNKNOWN {target_bid}")
    else:
        print(f"CANCELLED {target_bid}")

def main():
    global bookings
    bookings = []
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        parts = line.split()
        if parts[0] == "book":
            book_cmd(parts)
        elif parts[0] == "cancel":
            cancel_cmd(parts)

    rooms = {}
    for bid, room, date, start, end in bookings:
        rooms[room] = rooms.get(room, 0) + 1
    for room in sorted(rooms):
        active = [b for b in bookings if b[1] == room]
        total_minutes = 0
        for b in active:
            start_time = parse_time(b[3])
            end_time = parse_time(b[4])
            total_minutes += (end_time - start_time).total_seconds() / 60
        hours = int(total_minutes // 60)
        minutes = int(total_minutes % 60)
        print(f"{room} {rooms[room]} {f'{hours}:{minutes:02}'}")

if __name__ == "__main__":
    main()
